{
  "schemaVersion": "0.2",
  "slug": "image-compare",
  "name": "ImageCompare",
  "status": "experimental",
  "purpose": "Before/after image compare with a draggable divider and optional token-colored checkerboard.",
  "scenarios": [
    "Before/after image compare with a draggable divider.",
    "Transparent PNG results on a shared CheckerboardSurface."
  ],
  "props": {
    "beforeSrc": {
      "type": "string",
      "required": true,
      "description": "Before image URL."
    },
    "afterSrc": {
      "type": "string",
      "required": true,
      "description": "After image URL."
    },
    "checkerboard": {
      "type": "boolean",
      "required": false,
      "description": "Wrap in CheckerboardSurface for transparent media.",
      "default": true
    },
    "checkerboardContrast": {
      "type": "enum",
      "required": false,
      "description": "Checker A/B contrast when checkerboard is on. Defaults to strong for transparent results.",
      "values": ["default", "strong"],
      "default": "strong"
    },
    "orientation": {
      "type": "enum",
      "required": false,
      "description": "Divider axis.",
      "values": ["horizontal", "vertical"],
      "default": "horizontal"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Default."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page",
      "card",
      "stack",
      "workspace-split"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Hand-rolling a consumer checkerboard instead of checkerboard / checkerboardContrast props."
  ],
  "a11y": {
    "role": "slider",
    "keyboard": [
      "Arrow keys nudge the divider; Home/End jump to ends."
    ],
    "focus": "Root is focusable.",
    "labeling": "Pass label / beforeAlt / afterAlt.",
    "wcag": [
      "1.3.1",
      "1.4.1",
      "2.1.1"
    ]
  },
  "responsive": {
    "strategy": "Fluid.",
    "breakpoints": {
      "compact": "Default.",
      "medium": "Default.",
      "large": "Default."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS; horizontal divider uses inset-inline.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "image-compare",
    "states": [
      "default"
    ],
    "intents": [
      "compare-images"
    ]
  }
}

import { useCallback, useId, useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react'
import {
  CheckerboardSurface,
  type CheckerboardContrast,
} from '../checkerboard-surface/CheckerboardSurface.js'
import './styles.css'

export type ImageCompareOrientation = 'horizontal' | 'vertical'

export interface ImageCompareProps {
  beforeSrc: string
  afterSrc: string
  beforeAlt?: string
  afterAlt?: string
  position?: number
  defaultPosition?: number
  onPositionChange?: (value: number) => void
  orientation?: ImageCompareOrientation
  showKnob?: boolean
  checkerboard?: boolean
  /** Checker contrast when `checkerboard` is on. Defaults to `strong` for transparent results. */
  checkerboardContrast?: CheckerboardContrast
  label?: string
  children?: ReactNode
  className?: string
}

function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

export function ImageCompare({
  beforeSrc,
  afterSrc,
  beforeAlt = 'Before',
  afterAlt = 'After',
  position,
  defaultPosition = 0.5,
  onPositionChange,
  orientation = 'horizontal',
  showKnob = true,
  checkerboard = true,
  checkerboardContrast = 'strong',
  label = 'Compare before and after',
  className,
}: ImageCompareProps) {
  const id = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const [uncontrolled, setUncontrolled] = useState(defaultPosition)
  const value = position ?? uncontrolled

  const setValue = useCallback(
    (next: number) => {
      const clamped = clamp01(next)
      if (position === undefined) setUncontrolled(clamped)
      onPositionChange?.(clamped)
    },
    [onPositionChange, position],
  )

  const updateFromPointer = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      const el = rootRef.current
      if (!el) return
      const rect = el.getBoundingClientRect()
      if (orientation === 'vertical') {
        setValue((event.clientY - rect.top) / Math.max(rect.height, 1))
      } else {
        setValue((event.clientX - rect.left) / Math.max(rect.width, 1))
      }
    },
    [orientation, setValue],
  )

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? 0.1 : 0.02
    if (orientation === 'vertical') {
      if (event.key === 'ArrowUp') {
        event.preventDefault()
        setValue(value - step)
      } else if (event.key === 'ArrowDown') {
        event.preventDefault()
        setValue(value + step)
      }
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault()
      setValue(value - step)
    } else if (event.key === 'ArrowRight') {
      event.preventDefault()
      setValue(value + step)
    } else if (event.key === 'Home') {
      event.preventDefault()
      setValue(0)
    } else if (event.key === 'End') {
      event.preventDefault()
      setValue(1)
    }
  }

  const pct = `${value * 100}%`
  const clip =
    orientation === 'vertical' ? `inset(${pct} 0 0 0)` : `inset(0 0 0 ${pct})`
  const dividerStyle =
    orientation === 'vertical'
      ? { insetBlockStart: pct }
      : { insetInlineStart: pct }

  const body = (
    <div
      ref={rootRef}
      className={['cu-image-compare', `cu-image-compare--${orientation}`, className]
        .filter(Boolean)
        .join(' ')}
      data-ai-role="image-compare"
      data-ai-intent="compare-images"
      data-ai-state="default"
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(value * 100)}
      aria-orientation={orientation}
      aria-controls={id}
      onPointerDown={(event) => {
        event.currentTarget.setPointerCapture(event.pointerId)
        updateFromPointer(event)
      }}
      onPointerMove={(event) => {
        if (!event.currentTarget.hasPointerCapture(event.pointerId)) return
        updateFromPointer(event)
      }}
      onKeyDown={onKeyDown}
    >
      <img className="cu-image-compare__img cu-image-compare__img--before" src={beforeSrc} alt={beforeAlt} draggable={false} />
      <img
        id={id}
        className="cu-image-compare__img cu-image-compare__img--after"
        src={afterSrc}
        alt={afterAlt}
        draggable={false}
        style={{ clipPath: clip }}
      />
      <div
        className="cu-image-compare__divider"
        style={dividerStyle}
        data-show-knob={showKnob ? 'true' : 'false'}
        aria-hidden="true"
      />
    </div>
  )

  return checkerboard ? (
    <CheckerboardSurface className="cu-image-compare__surface" contrast={checkerboardContrast}>
      {body}
    </CheckerboardSurface>
  ) : (
    body
  )
}

.cu-image-compare__surface {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  inline-size: 100%;
  block-size: 100%;
  min-block-size: 16rem;
  flex: 1 1 auto;
}

.cu-image-compare {
  position: relative;
  inline-size: 100%;
  block-size: 100%;
  min-block-size: 16rem;
  flex: 1 1 auto;
  overflow: hidden;
  touch-action: none;
  cursor: ew-resize;
  user-select: none;
  border-radius: var(--cu-radius-md);
}

.cu-image-compare--vertical {
  cursor: ns-resize;
}

.cu-image-compare__img {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  object-fit: contain;
  pointer-events: none;
}

.cu-image-compare__divider {
  position: absolute;
  z-index: 2;
  pointer-events: none;
  background: var(--cu-color-accent-default, var(--cu-color-palette-brand));
}

.cu-image-compare--horizontal .cu-image-compare__divider {
  inset-block: 0;
  inline-size: 2px;
  transform: translateX(-50%);
}

.cu-image-compare--vertical .cu-image-compare__divider {
  inset-inline: 0;
  block-size: 2px;
  transform: translateY(-50%);
}

.cu-image-compare__divider[data-show-knob='true']::after {
  content: '';
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  inline-size: 1rem;
  block-size: 1rem;
  border-radius: 999px;
  border: 2px solid var(--cu-color-accent-default, var(--cu-color-palette-brand));
  background: var(--cu-color-background-elevated, var(--cu-color-background-default));
  box-shadow: var(--cu-shadow-sm, 0 1px 2px rgb(0 0 0 / 12%));
  transform: translate(-50%, -50%);
}

.cu-image-compare:focus-visible {
  outline: 2px solid var(--cu-color-accent-default, var(--cu-color-palette-brand));
  outline-offset: 2px;
}
